import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:neat/features/feature_gen/domain/services/project_constraints.dart';
import 'package:neat/features/generation/domain/services/templates/core_package_templates.dart';

/// Real bug, found via a real project: the Workshop added a split feature
/// package with NEAT's current template versions (freezed ^4.0.2) to a
/// project generated by an older NEAT (freezed ^3.2.5) — the workspace's
/// version solving failed. See ProjectConstraints' doc.
void main() {
  group('ProjectConstraints.align', () {
    final template = CorePackageTemplates.featurePackagePubspec(
      featurePackageName: 'worksite',
      corePackageName: 'core',
      httpClient: 'supabase',
      hasGoRouterBuilder: true,
    );

    test(
      "dependencies + dev_dependencies follow the project's constraints",
      () {
        final out = ProjectConstraints.align(template, const {
          'freezed': '^3.2.5',
          'build_runner': '^2.15.0',
          'riverpod_generator': '^4.0.3',
          'hooks_riverpod': '^3.3.1',
          'go_router_builder': '^4.3.0',
        });
        expect(out, contains('  freezed: ^3.2.5'));
        expect(out, contains('  build_runner: ^2.15.0'));
        expect(out, contains('  riverpod_generator: ^4.0.3'));
        expect(out, contains('  hooks_riverpod: ^3.3.1'));
        expect(out, contains('  go_router_builder: ^4.3.0'));
        expect(out, isNot(contains('freezed: ^4.0.2')));
      },
    );

    test(
      "never touches environment's sdk (a language version, not a dependency)",
      () {
        // The project's root pubspec typically declares a much newer sdk —
        // aligning it would silently move the package's language version.
        final out = ProjectConstraints.align(template, const {
          'sdk': '^3.13.2',
        });
        // Whatever the template declares stays (the default, here).
        expect(
          out,
          contains('  sdk: ${CorePackageTemplates.defaultSdkConstraint}'),
        );
        expect(out, isNot(contains('^3.13.2')));
      },
    );

    test('path deps and packages unknown to the project are left alone', () {
      final out = ProjectConstraints.align(template, const {'core': '^1.0.0'});
      expect(out, contains('  core:\n    path: ../core'));
      expect(out, contains('  skeletonizer: ^2.1.3'));
    });

    test('range constraints are quoted to stay valid YAML', () {
      final out = ProjectConstraints.align(template, const {
        'freezed': '>=3.2.5 <4.0.0',
      });
      expect(out, contains('  freezed: ">=3.2.5 <4.0.0"'));
    });
  });

  group('ProjectConstraints.read', () {
    late Directory dir;
    setUp(() => dir = Directory.systemTemp.createTempSync('neat_constraints_'));
    tearDown(() => dir.deleteSync(recursive: true));

    test('root wins; packages fill the gaps; path/sdk deps are skipped', () {
      File('${dir.path}/pubspec.yaml').writeAsStringSync('''
name: app
environment:
  sdk: ^3.13.2
dependencies:
  flutter:
    sdk: flutter
  freezed_annotation: ^3.1.0
  core:
    path: packages/core
dev_dependencies:
  freezed: ^3.2.5
''');
      Directory('${dir.path}/packages/core').createSync(recursive: true);
      File('${dir.path}/packages/core/pubspec.yaml').writeAsStringSync('''
name: core
dependencies:
  freezed_annotation: ^9.9.9
  logger: ^2.7.0
dev_dependencies:
  freezed: ^4.0.2
''');
      final c = ProjectConstraints.read(dir.path);
      expect(c['freezed'], '^3.2.5', reason: 'root wins over a package');
      expect(c['freezed_annotation'], '^3.1.0');
      expect(c['logger'], '^2.7.0', reason: 'package-only deps still count');
      expect(c.containsKey('core'), isFalse, reason: 'path dep');
      expect(c.containsKey('flutter'), isFalse, reason: 'sdk dep');
      expect(c.containsKey('sdk'), isFalse, reason: 'environment is not a dep');
    });
  });
}
